        sse_encode_box_autoadd_peer(peer, serializer);
      case Event_PeerGone(id: final id):
        sse_encode_i_32(1, serializer);
        sse_encode_String(id, serializer);
      case Event_PairRequest(peerId: final peerId, name: final name, code: final code, incoming: final incoming):
        sse_encode_i_32(2, serializer);
        sse_encode_String(peerId, serializer);
        sse_encode_String(name, serializer);
        sse_encode_String(code, serializer);
        sse_encode_bool(incoming, serializer);
      case Event_PairFinished(
        peerId: final peerId,
        name: final name,
        ok: final ok,
        code: final code,
        message: final message,
      ):
        sse_encode_i_32(3, serializer);
        sse_encode_String(peerId, serializer);
        sse_encode_String(name, serializer);
        sse_encode_bool(ok, serializer);
        sse_encode_String(code, serializer);
        sse_encode_String(message, serializer);
      case Event_TransferOffer(
        id: final id,
        peerId: final peerId,
        peerName: final peerName,
        name: final name,
        size: final size,
      ):
        sse_encode_i_32(4, serializer);
        sse_encode_String(id, serializer);
        sse_encode_String(peerId, serializer);
        sse_encode_String(peerName, serializer);
        sse_encode_String(name, serializer);
        sse_encode_u_64(size, serializer);
      case Event_TransferStarted(
        id: final id,
        peerId: final peerId,
        peerName: final peerName,
        name: final name,
        size: final size,
        incoming: final incoming,
      ):
        sse_encode_i_32(5, serializer);
        sse_encode_String(id, serializer);
        sse_encode_String(peerId, serializer);
        sse_encode_String(peerName, serializer);
        sse_encode_String(name, serializer);
        sse_encode_u_64(size, serializer);
        sse_encode_bool(incoming, serializer);
      case Event_TransferProgress(id: final id, done: final done, total: final total, bytesPerSec: final bytesPerSec):
        sse_encode_i_32(6, serializer);
        sse_encode_String(id, serializer);
        sse_encode_u_64(done, serializer);
        sse_encode_u_64(total, serializer);
        sse_encode_u_64(bytesPerSec, serializer);
      case Event_TransferNote(id: final id, message: final message):
        sse_encode_i_32(7, serializer);
        sse_encode_String(id, serializer);
        sse_encode_String(message, serializer);
      case Event_TransferFinished(
